package user

import (
	"context"
	"fmt"
)

func (s *userSessionProviderImpl) GetCurrentUserSessionOrNull(ctx context.Context) (*UserSession, error) {
    context, err := s.securityContext.GetContext(ctx)
    if err != nil || context == nil {
        return nil, nil
    }
    tokenPrincipal, ok := context.Authentication.Principal.(TokenPrincipal)
    if !ok {
        return nil, fmt.Errorf("invalid principal type")
    }
    user, err := s.repo.FindByID(ctx, tokenPrincipal.UserID)
    if err != nil {
        return nil, fmt.Errorf("find user by id: %w", err)
    }
    return &UserSession{User: user, Token: tokenPrincipal.Token}, nil
}
